# --- api/cron-devocional.js (novo arquivo) ---
_f = Path("api/cron-devocional.js")
_f.write_text("import { verificarCron, getDeniseNumber, sendWhatsappText, getSupabaseAdmin } from './_cronlib.js'\n\nfunction dataIsoBR() {\n  return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(new Date())\n}\n\nexport default async function handler(req, res) {\n  if (!verificarCron(req)) {\n    res.status(401).json({ error: 'Nao autorizado.' })\n    return\n  }\n  const numero = getDeniseNumber()\n  if (!numero) {\n    res.status(500).json({ error: 'DENISE_WHATSAPP_NUMBER nao configurada.' })\n    return\n  }\n  try {\n    const supabase = getSupabaseAdmin()\n    const hojeIso = dataIsoBR()\n    if (supabase) {\n      const { data: snap } = await supabase.from('app_snapshot').select('data').eq('id', 'denise').maybeSingle()\n      const d = snap?.data || {}\n      const devocionais = Array.isArray(d.dos_devocionais) ? d.dos_devocionais : []\n      if (devocionais.some((e) => e.data === hojeIso)) {\n        res.status(200).json({ ok: true, ja_feito: true })\n        return\n      }\n    }\n    const texto = '🙏 Bom dia! Hora do devocional.\\n\\nExiste um mandamento a obedecer? Uma promessa a reivindicar? Um pecado a evitar? Uma aplicação a fazer? Algo novo sobre Deus?\\n\\nPergunte também: Quem? O quê? Quando? Onde? Por quê?\\n\\nPode me responder por aqui quando terminar que eu registro no seu histórico.'\n    await sendWhatsappText(numero, texto)\n    res.status(200).json({ ok: true })\n  } catch (err) {\n    res.status(500).json({ error: err?.message || 'erro desconhecido' })\n  }\n}\n", encoding="utf-8")
print("OK - api/cron-devocional.js criado.")

# --- api/agenda-sync-google.js (novo arquivo) ---
_f = Path("api/agenda-sync-google.js")
_f.write_text("import { getSupabaseAdmin, insertGoogleCalendarEvento } from './_cronlib.js'\n\nexport default async function handler(req, res) {\n  if (req.method !== 'POST') {\n    res.status(405).json({ error: 'Metodo nao permitido.' })\n    return\n  }\n  try {\n    const body = req.body || {}\n    const nome = String(body.nome || '').trim()\n    const data = String(body.data || '').trim()\n    const hora = body.hora ? String(body.hora).trim() : ''\n    if (!nome || !/^\\d{4}-\\d{2}-\\d{2}$/.test(data)) {\n      res.status(400).json({ error: 'nome e data (YYYY-MM-DD) sao obrigatorios.' })\n      return\n    }\n    const supabase = getSupabaseAdmin()\n    if (!supabase) {\n      res.status(500).json({ error: 'Supabase nao configurado.' })\n      return\n    }\n    const evento = await insertGoogleCalendarEvento(supabase, { nome, data, hora })\n    res.status(200).json({ ok: true, google_evento: evento })\n  } catch (err) {\n    res.status(500).json({ error: err?.message || 'erro desconhecido' })\n  }\n}\n", encoding="utf-8")
print("OK - api/agenda-sync-google.js criado.")

